import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))

        adj = [[] for _ in range(n + 1)]

        for _ in range(m):
            u = int(next(iterator))
            v = int(next(iterator))
            adj[u].append(v)
            adj[v].append(u)

    except StopIteration:
        return

    # Check for Hamiltonian Path
    # Since N is small (<= 10), we can use backtracking.
    # We try starting from every node.

    visited = [False] * (n + 1)

    def backtrack(node, count):
        if count == n:
            return True

        visited[node] = True

        for neighbor in adj[node]:
            if not visited[neighbor]:
                if backtrack(neighbor, count + 1):
                    return True

        visited[node] = False
        return False

    found = False
    for start_node in range(1, n + 1):
        # Reset visited for each start node attempt
        for i in range(1, n + 1):
            visited[i] = False

        if backtrack(start_node, 1):
            found = True
            break

    print(1 if found else 0)

if __name__ == "__main__":
    solve()
